def flatten(nodes, start):                                                  # nodes: list of {val, next, child} (indices, -1 = none)
    result = []
    def walk(idx):
        while idx != -1:
            result.append(nodes[idx]['val'])
            if nodes[idx]['child'] != -1:
                walk(nodes[idx]['child'])                                  # recursively flatten this child branch FIRST (depth-first order)
            idx = nodes[idx]['next']
    walk(start)
    return result


if __name__ == "__main__":
    nodes = [
        {"val": 1, "next": 1, "child": -1},
        {"val": 2, "next": -1, "child": 2},
        {"val": 3, "next": -1, "child": -1},
    ]
    print(flatten(nodes, 0))

