import java.util.*;

public class Main {
    List<Integer> flatten(int[][] nodes, int start) {                              // nodes[i] = {val, next, child} (indices, -1 = none)
        List<Integer> result = new ArrayList<>();
        flattenHelper(nodes, start, result);
        return result;
    }

    void flattenHelper(int[][] nodes, int idx, List<Integer> result) {
        while (idx != -1) {
            result.add(nodes[idx][0]);
            if (nodes[idx][2] != -1) {
                flattenHelper(nodes, nodes[idx][2], result);                          // recursively flatten this child branch FIRST (depth-first order)
            }
            idx = nodes[idx][1];
        }
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[][] nodes = {{1, 1, -1}, {2, -1, 2}, {3, -1, -1}};
        System.out.println(solution.flatten(nodes, 0));
    }
}

