void flattenHelper(vector<array<int,3>>& nodes, int idx, vector<int>& result) {   // nodes[i] = {val, next, child} (indices, -1 = none)
    while (idx != -1) {
        result.push_back(nodes[idx][0]);
        if (nodes[idx][2] != -1) {
            flattenHelper(nodes, nodes[idx][2], result);                                // recursively flatten this child branch FIRST (depth-first order)
        }
        idx = nodes[idx][1];
    }
}

vector<int> flatten(vector<array<int,3>>& nodes, int start) {
    vector<int> result;
    flattenHelper(nodes, start, result);
    return result;
}

int main() {
    vector<array<int,3>> nodes = {{1, 1, -1}, {2, -1, 2}, {3, -1, -1}};
    vector<int> result = flatten(nodes, 0);
    for (int v : result) cout << v << " ";
    cout << endl;
    return 0;
}

