import java.util.*;

public class Main {
    Node flatten(Node head) {
        Node node = head;
        while (node != null) {
            if (node.child != null) {
                Node next = node.next;                                                 // remember what originally came after this node
                Node child = node.child;
                node.next = child;                                                       // splice: this node now connects directly to its child
                child.prev = node;
                node.child = null;

                Node tail = child;                                                       // walk to the child branch's own tail
                while (tail.next != null) tail = tail.next;
                tail.next = next;                                                        // the child branch's tail reconnects to the ORIGINAL next
                if (next != null) next.prev = tail;
            }
            node = node.next;                                                            // continue forward (now walking INTO the just-spliced child)
        }
        return head;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        Node n3 = new Node(3);
        Node n2 = new Node(2);
        Node n1 = new Node(1);
        n1.next = n2; n2.prev = n1;
        n1.child = n3;
        Node result = solution.flatten(n1);
        StringBuilder sb = new StringBuilder();
        while (result != null) { sb.append(result.val).append(" "); result = result.next; }
        System.out.println(sb.toString().trim());
    }
}

